def verify():
    assert abs(2e9 * 1.5 / 3e9 - 1) < 1e-12 and abs(1 / (0.2 + 0.2) - 2.5) < 1e-12 and abs(0.9 ** 2 - 0.81) < 1e-12
    assert 2 + 127 == 129 and 150 - 256 == -106 and 1000 + 5 * 4 == 1020
    assert 32 * 1024 // 64 == 512 and 32 - 9 - 6 == 17
    assert 2 ** 20 * 4 == 4 * 2 ** 20 and abs(0.98 * 101 + 0.02 * 201 - 103) < 1e-9
    assert abs(1000 * 500 / 1e9 * 100 - 0.05) < 1e-12 and abs(1 / (0.1 + 0.9 / 16) - 6.4) < 1e-9
    assert abs(60 / 7200 / 2 * 1e3 - 4.1667) < 1e-3 and abs(0.2 * 0.5 + 1 - 1.1) < 1e-12


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
